            if arr[j] <= pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[right] = arr[right], arr[i]
        if i < k:
            return quickselect(arr, i + 1, right, k)
        elif i > k:
            return quickselect(arr, left, i - 1, k)
        else:
            return arr[i]

    # Find the k-th largest frequency using quickselect
    kth_freq = quickselect(counts[:], 0, len(counts) - 1, k - 1)

    # Collect all numbers with frequency >= kth_freq
    result = []
    for num in unique_nums:
        if count[num] >= kth_freq:
