    lens = _lens(f)
    if any(L in lens for L in (n + 1, n + 2)) and f["clist_iter"] >= 1:
        return "hash_set"
    if f["c_calls"].get("sum", 0) >= 1 or f["c_calls"].get("len", 0) >= 1 and f["clist_iter"] <= 2:
