def solve(haystack, needle):
    m = len(needle)
    fail = [0] * m
    j = 0
    for i in range(1, m):
        while j and needle[i] != needle[j]:
            j = fail[j - 1]
        if needle[i] == needle[j]:
            j += 1
        fail[i] = j
    j = 0
    for i, c in enumerate(haystack):
        while j and c != needle[j]:
            j = fail[j - 1]
        if c == needle[j]:
            j += 1
        if j == m:
            return i - m + 1
    return -1

bench_files.references/rabin_karp.py:
def solve(haystack, needle):
    n, m = len(haystack), len(needle)
    if m > n:
        return -1
    base, mod = 256, 1_000_000_007
    hn = hw = 0
    for i in range(m):
        hn = (hn * base + ord(needle[i])) % mod
        hw = (hw * base + ord(haystack[i])) % mod
    high = pow(base, m - 1, mod)
    for i in range(n - m + 1):
        if hn == hw and haystack[i:i + m] == needle:
            return i
        if i + m < n:
            hw = ((hw - ord(haystack[i]) * high) * base + ord(haystack[i + m])) % mod
    return -1

