def runtime_label(task: str, trace: dict) -> str:
    if trace.get("error") and not trace["probes"]:
        return "unknown"
    try:
        return RULES[task](trace)
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        return "unknown"

