def solve(intervals):
    if not intervals:
        return []

    # Create an interval tree
    class IntervalTreeNode:
        def __init__(self, start, end):
            self.start = start
            self.end = end
            self.left = None
            self.right = None
            self.intervals = []

    def build_tree(intervals, low, high):
        if not intervals:
            return None
        mid = (low + high) // 2
        root = IntervalTreeNode(mid, mid)
        for interval in intervals:
            if interval[0] <= mid <= interval[1]:
                root.intervals.append(interval)
        left_intervals = []
        right_intervals = []
        for interval in intervals:
            if interval[1] < mid:
                left_intervals.append(interval)
            elif interval[0] > mid:
                right_intervals.append(interval)
        root.left = build_tree(left_intervals, low, mid)
        root.right = build_tree(right_intervals, mid, high)
        return root

    # Helper to insert intervals into the tree
    def insert(root, interval):
        if not root:
            return
        if interval[1] < root.start:
            insert(root.left, interval)
        elif interval[0] > root.end:
            insert(root.right, interval)
        else:
            root.intervals.append(interval)

    # Helper to collect intervals from the tree
    def collect(root, result):
        if not root:
            return
        collect(root.left, result)
        result.extend(root.intervals)
        collect(root.right, result)

    # Build the tree
    low = min(interval[0] for interval in intervals)
    high = max(interval[1] for interval in intervals)
    root = build_tree(intervals, low, high)

    # Insert all intervals into the tree
    for interval in intervals:
        insert(root, interval)

    # Collect all intervals from the tree
    merged = []
    collect(root, merged)

    # Sort intervals by start
    merged.sort()
    # Merge overlapping intervals
    result = []
    for interval in merged:
        if not result or result[-1][1] < interval[0]:
            result.append(interval)
        else:
            result[-1][1] = max(result[-1][1], interval[1])
    return result

