    intervals.sort(key=lambda x: x[1])

    # dp[i] will store the index of the last non-overlapping interval before i
    dp = [0] * len(intervals)

    # The last compatible interval for the first interval is itself
    dp[0] = 0

    for i in range(1, len(intervals)):
        # Binary search for the largest j < i such that intervals[j][1] <= intervals[i][0]
        # We use bisect_right on the end times up to index i-1
        end_times = [intervals[j][1] for j in range(i)]
        j = bisect.bisect_right(end_times, intervals[i][0]) - 1
        if j >= 0:
            dp[i] = j
        else:
            dp[i] = -1  # No compatible interval found

    # The maximum length of non-overlapping intervals is the length of the longest increasing subsequence
    # Using the dp array to find LIS
    lis = [1] * len(intervals)
    for i in range(1, len(intervals)):
        max_len = 1
        for j in range(i):
            if dp[i] == j and lis[j] + 1 > max_len:
                max_len = lis[j] + 1
        lis[i] = max_len

    return len(intervals) - max(lis)

