from collections import deque

def solve(n, edges):
    def is_cyclic():
        visited = [False] * n
        parent = [-1] * n

        for start in range(n):
            if not visited[start]:
                queue = deque()
                queue.append(start)
                visited[start] = True
                parent[start] = -1

                while queue:
                    node = queue.popleft()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            parent[neighbor] = node
                            queue.append(neighbor)
                        elif parent[node] != neighbor:
                            return True
        return False

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    return is_cyclic()

