def solve(n, edges):
    def bfs_cycle_check(start, adj):
        visited = [False] * n
        parent = [-1] * n
        queue = deque([start])
        visited[start] = True

        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    return True
        return False

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            if bfs_cycle_check(i, adj):
                return True
            visited[i] = True
    return False

