"""Frozen AST rules for R3_topological_order (snapshot of bench/common/astrules.py; shared helpers included)."""

"""Static (AST) labeller: imports, call names, loop/recursion structure, characteristic expressions;
identifier hints are weak evidence only.  ast_label(task, code) -> mode | 'other' | 'unknown' | 'invalid'."""

from __future__ import annotations

import ast
import re
from collections import Counter


class F:
    """AST feature bag of one program."""

    def __init__(self, code: str):
        self.code = code
        self.tree = ast.parse(code)
        self.calls = Counter()
        self.attr_calls = Counter()
        self.imports = set()
        self.names = Counter()
        self.funcs = {}
        self.recursive = set()
        self.max_loop_depth = 0
        self.n_loops = 0
        self.classes = 0
        self.decorators = Counter()
        self.bitand_neg = False
        self.pop0 = 0
        self.pop_noarg = 0
        self.popleft = 0
        self.subscript_nested = 0
        self.consts = Counter()
        for node in ast.walk(self.tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    self.imports.add(a.name.split(".")[0])
            elif isinstance(node, ast.ImportFrom):
                if node.module:
                    self.imports.add(node.module.split(".")[0])
                for a in node.names:
                    self.imports.add(a.name)
            elif isinstance(node, ast.Call):
                fn = node.func
                if isinstance(fn, ast.Name):
                    self.calls[fn.id] += 1
                elif isinstance(fn, ast.Attribute):
                    self.attr_calls[fn.attr] += 1
                    if isinstance(fn.value, ast.Name):
                        self.calls[f"{fn.value.id}.{fn.attr}"] += 1
                    if fn.attr == "pop":
                        if not node.args:
                            self.pop_noarg += 1
                        elif isinstance(node.args[0], ast.Constant) and node.args[0].value == 0:
                            self.pop0 += 1
                    if fn.attr == "popleft":
                        self.popleft += 1
            elif isinstance(node, ast.Name):
                self.names[node.id] += 1
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                self.funcs[node.name] = node
                for d in node.decorator_list:
                    dn = d.func if isinstance(d, ast.Call) else d
                    nm = dn.attr if isinstance(dn, ast.Attribute) else (dn.id if isinstance(dn, ast.Name) else "?")
                    self.decorators[nm] += 1
                for sub in ast.walk(node):
                    if isinstance(sub, ast.Call) and isinstance(sub.func, ast.Name) and sub.func.id == node.name:
                        self.recursive.add(node.name)
                    if isinstance(sub, ast.Call) and isinstance(sub.func, ast.Attribute) and sub.func.attr == node.name:
                        self.recursive.add(node.name)
            elif isinstance(node, ast.ClassDef):
                self.classes += 1
            elif isinstance(node, ast.BinOp) and isinstance(node.op, ast.BitAnd):
                for side in (node.left, node.right):
                    if isinstance(side, ast.UnaryOp) and isinstance(side.op, ast.USub):
                        self.bitand_neg = True
            elif isinstance(node, ast.Subscript) and isinstance(node.slice, ast.Subscript):
                self.subscript_nested += 1
            elif isinstance(node, ast.Constant) and isinstance(node.value, (int, str)):
                self.consts[node.value] += 1
        self._loop_depth(self.tree, 0)
        self.low = code.lower()
        self.idents = {n.lower() for n in self.names} | {f.lower() for f in self.funcs}

    def _loop_depth(self, node, d):
        for ch in ast.iter_child_nodes(node):
            if isinstance(ch, (ast.For, ast.While)):
                self.n_loops += 1
                self.max_loop_depth = max(self.max_loop_depth, d + 1)
                self._loop_depth(ch, d + 1)
            elif isinstance(ch, (ast.FunctionDef, ast.Lambda, ast.AsyncFunctionDef, ast.ClassDef)):
                self._loop_depth(ch, 0)
            else:
                self._loop_depth(ch, d)

    def has(self, *names):
        return any(self.calls.get(n) or self.attr_calls.get(n) for n in names)

    def ident(self, *subs):
        return any(any(s in i for s in subs) for i in self.idents)

    def rx(self, pattern):
        return re.search(pattern, self.code) is not None

    @property
    def memo(self):
        return bool(self.decorators.get("lru_cache") or self.decorators.get("cache") or self.ident("memo", "cache"))


def _bisect(f):
    return f.has("bisect_left", "bisect_right", "bisect", "insort", "insort_left", "insort_right")


def _manual_bsearch(f):
    return f.ident("mid") and f.rx(r"while\s+\w+\s*(<|<=)\s*\w+")


def _uf(f):
    return (f.ident("parent", "root") and (f.ident("find") or "find" in f.funcs)) or f.ident("union", "dsu", "disjoint")


def _heapish(f):
    return f.has("heappush", "heappop", "heapify", "heappushpop", "heapreplace", "nlargest", "nsmallest") or \
        f.has("PriorityQueue")


def t03(f):
    if f.has("nsmallest", "nlargest"):
        return "size_k_heap"
    if f.has("heapify") and f.has("heappop") and not (f.has("heappush") and f.rx(r"len\(\s*\w+\s*\)\s*>")):
        return "heapify_pop"
    if f.has("heappush", "heappushpop", "heapreplace"):
        if f.rx(r"len\(\s*\w+\s*\)\s*(>|>=|==|<|<=)\s*k") or f.has("heappushpop", "heapreplace"):
            return "size_k_heap"
        if f.has("heappop"):
            return "heapify_pop"
    if f.rx(r"\b5\b") and (f.ident("median", "group", "chunk") or f.rx(r":\s*\w+\s*\+\s*5\]")) and f.recursive | {"x"}:
        if f.ident("median") or f.rx(r"range\([^)]*,\s*5\)"):
            return "median_of_medians"
    if f.rx(r"\[0\]\s*\*\s*\(?\s*(max|hi|high|max_val|maxv|mx|\w+_max|20001|20000|10001)") or \
            (f.ident("count") and f.rx(r"\[0\]\s*\*\s*\(") and f.has("min", "max")) or \
            f.rx(r"for\s+\w+\s+in\s+range\(\s*(min|lo|low|min_val|mn|-\s*10000|offset)\w*") and f.ident("count", "freq"):
        return "counting_sort"
    if (f.has("Counter") or f.ident("count", "freq")) and f.rx(r"sorted\(\s*\w+\.?(keys|items)?\(?\)?\s*\)"):
        return "unknown"
    if f.ident("pivot", "partition", "quickselect", "select") and not f.has("sort", "sorted"):
        return "quickselect"
    if f.ident("pivot") and f.recursive:
        return "quickselect"
    if f.has("sorted", "sort") and not f.ident("pivot"):
        return "full_sort"
    if f.ident("pivot"):
        return "quickselect"
    return "unknown"


def t04(f):
    if f.has("find", "index") and f.rx(r"\.(find|index)\(\s*needle") or f.rx(r"needle\s+in\s+haystack"):
        if not f.rx(r"for\s+\w+\s+in\s+range"):
            return "builtin"
    if f.rx(r"needle\s*\+\s*['\"]") or f.rx(r"['\"][$#|@]['\"]\s*\+") or f.ident("z_arr", "zarr", "z_func", "zfunc") or \
            (f.ident("z") and f.rx(r"\bz\s*=\s*\[0\]")):
        return "z_algorithm"
    if f.ident("lps", "fail", "prefix_func", "pi", "kmp", "next_arr", "partial") and f.rx(r"\w+\[\s*\w+\s*-\s*1\s*\]"):
        return "kmp"
    if f.has("ord") and (f.has("pow") or f.rx(r"%\s*\w*(mod|prime|q|MOD)\w*") or f.rx(r"\*\*")) or f.ident("rolling", "hash"):
        return "rabin_karp"
    if f.ident("shift", "bad_char", "badchar", "bad_character", "skip", "last_occ", "last", "table", "horspool", "occ") and \
            (f.rx(r"-=\s*1") or f.rx(r"range\([^)]*-\s*1\s*,\s*-1\s*,\s*-1\)")):
        return "bmh"
    if f.has("startswith") or f.rx(r"haystack\[\s*\w+\s*:\s*\w+\s*\+\s*\w+\s*\]\s*==") or \
            f.rx(r"==\s*needle") or f.max_loop_depth >= 2:
        return "naive"
    if f.has("find", "index") or f.rx(r"\bin\s+haystack"):
        return "builtin"
    return "unknown"


def t05(f):
    if f.max_loop_depth >= 2 and not f.has("sorted", "sort") and not f.rx(r"in\s+\w*(seen|map|dict|lookup|index|pos|hash)\w*"):
        if f.rx(r"\[\s*i\s*\]\s*\+\s*\w+\[\s*j\s*\]") or f.rx(r"range\(\s*i\s*\+\s*1"):
            return "brute_force"
    if f.has("sorted", "sort"):
        if _bisect(f) or _manual_bsearch(f) and not f.ident("left", "right") or f.ident("mid"):
            if not (f.ident("left") and f.ident("right") and f.rx(r"while\s+left\s*<\s*right") and not f.ident("mid")):
                return "sort_binary_search"
        if f.rx(r"while\s+\w+\s*<\s*\w+") and (f.rx(r"-=\s*1") or f.rx(r"\+=\s*1")):
            return "sort_two_pointers"
    if f.rx(r"\bin\s+\w+") and (f.rx(r"\{\s*\}") or f.has("dict", "defaultdict")):
        return "hash_map"
    if f.max_loop_depth >= 2:
        return "brute_force"
    return "unknown"


def t06(f):
    if f.ident("slow", "tortoise") and f.ident("fast", "hare"):
        return "floyd"
    if f.rx(r"nums\[\s*nums\[") and f.n_loops >= 2 and not f.rx(r"=\s*-"):
        return "floyd"
    if f.ident("mid") and f.rx(r"<=\s*mid|mid\s*>=") and (f.ident("count", "cnt") or f.has("sum")):
        return "value_binary_search"
    if f.rx(r"nums\[\s*\w+\s*\]\s*\*=\s*-1") or f.rx(r"=\s*-\s*nums\[") or f.rx(r"nums\[[^\]]*abs") or \
            (f.has("abs") and f.rx(r"<\s*0")):
        return "index_marking"
    if f.rx(r"nums\[\s*nums\[\s*\w+\s*\]\s*\]\s*,\s*nums\[") or f.rx(r"nums\[\s*\w+\s*\]\s*,\s*nums\[\s*nums"):
        return "index_marking"
    if f.has("sorted", "sort") and f.rx(r"\[\s*\w+\s*\]\s*==\s*\w+\[\s*\w+\s*[-+]\s*1\s*\]"):
        return "sort_adjacent"
    if f.has("set", "Counter", "defaultdict") or f.rx(r"\{\s*\}") or f.rx(r"\[\s*(0|False)\s*\]\s*\*"):
        return "hash_set"
    if f.has("sorted", "sort"):
        return "sort_adjacent"
    if f.has("sum") or f.rx(r"\^"):
        return "other"
    if f.rx(r"nums\[\s*\w+\s*-\s*1\s*\]\s*==\s*nums\[\s*\w+\s*\]|nums\[\s*\w+\s*\]\s*==\s*nums\[\s*\w+\s*[-+]\s*1\s*\]"):
        return "sort_adjacent"
    return "unknown"


def t08(f):
    if f.rx(r"sqrt\(\s*5|5\s*\*\*\s*0?\.5|phi|golden"):
        return "other"
    mat = f.rx(r"\[\s*\[\s*1\s*,\s*1\s*\]\s*,\s*\[\s*1\s*,\s*0\s*\]\s*\]") or f.ident("matrix", "mat_", "matmul", "mat")
    if mat and (f.rx(r"\[0\]\[0\]") or f.rx(r"\[\s*\[")):
        return "matrix_power"
    if f.rx(r"2\s*\*\s*\w+\s*-\s*\w+") and (f.rx(r">>\s*1|//\s*2") or f.ident("doubling")):
        return "fast_doubling"
    if f.recursive and (f.memo or f.ident("memo", "cache", "dp")):
        return "memo_recursion"
    if f.recursive and not f.memo:
        return "other"
    if f.n_loops >= 1:
        return "iteration"
    return "unknown"


def t10(f):
    if _uf(f):
        return "union_find"
    if f.popleft or f.pop0 or f.has("Queue") or (f.has("deque") and not f.pop_noarg):
        return "bfs"
    if f.recursive or f.pop_noarg or f.has("LifoQueue"):
        return "dfs"
    if f.has("min") and f.rx(r"while\s+\w*chang\w*") or f.ident("label", "changed"):
        return "label_propagation"
    return "unknown"


def t11(f):
    if f.bitand_neg or f.ident("fenwick", "bit", "tree", "segment"):
        return "fenwick"
    if _bisect(f) or (f.ident("tail", "pile", "sub") and (_manual_bsearch(f) or f.ident("mid", "lo", "left"))):
        return "patience_bisect"
    if f.max_loop_depth >= 2 or (f.recursive and f.memo):
        return "quadratic_dp"
    return "unknown"


def t13(f):
    if f.classes and f.ident("max_end", "maxend", "max_high", "interval_tree", "itree", "node", "insert"):
        return "interval_tree"
    if _uf(f):
        return "union_find"
    if f.has("sorted", "sort"):
        return "sort_sweep"
    return "unknown"


def t14(f):
    if f.attr_calls.get("most_common"):
        if f.rx(r"most_common\(\s*\)"):
            return "sort_by_count"
        return "heap"
    if _heapish(f):
        return "heap"
    if f.ident("bucket", "freq_list", "buckets") or f.rx(r"\[\s*\[\s*\]\s*for\s+\w+\s+in\s+range\(\s*len\(\s*nums\s*\)\s*\+\s*1"):
        return "bucket_sort"
    if f.ident("pivot", "partition", "quickselect", "select"):
        return "quickselect_counts"
    if f.has("sorted", "sort"):
        return "sort_by_count"
    return "unknown"


def r1(f):
    if f.recursive and (f.memo or f.ident("memo", "dp", "cache")):
        return "memo_recursion"
    if (_bisect(f) or _manual_bsearch(f)) and (f.ident("dp") or f.rx(r"\[0\]\s*\*\s*\(")):
        return "dp_bisect"
    if f.max_loop_depth >= 2 and (f.ident("dp", "longest", "best", "chain") or f.rx(r"\[1\]\s*\*")):
        return "dag_longest_path"
    if f.has("sorted", "sort"):
        return "greedy_end"
    return "unknown"


def r2(f):
    if f.rx(r"len\(\s*edges\s*\)\s*(>|>=|!=|==)\s*\w*n\w*\s*-") or f.rx(r"edge\w*count\w*\s*(>|>=)") or \
            f.rx(r"(>|>=)\s*\w*node\w*count") or f.ident("edge_count", "num_edges", "edges_count", "edge_cnt", "ecount"):
        return "edge_count"
    if _uf(f):
        return "union_find"
    if f.popleft or f.pop0 or f.has("Queue"):
        return "bfs_parent"
    if f.recursive or f.pop_noarg:
        return "dfs_parent"
    return "unknown"


def r3(f):
    indeg = f.ident("indeg", "in_deg", "in_degree", "indegree", "incoming")
    if indeg and (f.popleft or f.pop0 or f.pop_noarg or f.has("deque", "Queue", "heappop")):
        return "kahn"
    if f.recursive or f.ident("color", "colour", "state", "visiting", "on_stack", "onstack", "temp_mark", "gray"):
        if f.recursive or f.pop_noarg:
            return "dfs_postorder"
    if f.ident("depth", "level", "layer", "longest", "dist") and f.has("sorted", "sort"):
        return "layering"
    if indeg or f.ident("remaining", "removed", "done"):
        return "source_removal"
    return "unknown"


def r6(f):
    if _bisect(f):
        return "bisect_module"
    if f.rx(r"(\*=\s*2|<<=\s*1|\*\s*2\b)") and f.ident("bound", "step", "jump", "exp", "hi", "high", "end", "i"):
        if f.rx(r"while\s+\w+\s*<\s*(len|n)\b.*\w+\s*\]\s*(<|<=)") or f.ident("bound", "exp"):
            return "exponential_search"
    if f.ident("mid"):
        if f.rx(r"while\s+\w+\s*(>|>=)\s*0\s+and\s+nums\[") or f.rx(r"while\s+\w+\s*<\s*(len\(nums\)|n)\s*(-\s*1)?\s+and\s+nums\["):
            return "binary_expand"
        return "binary_search"
    if f.has("index") or f.rx(r"for\s+\w+\s*(,\s*\w+)?\s+in\s+(enumerate|range)"):
        return "linear_scan"
    return "unknown"


RULES = {"T03": t03, "T04": t04, "T05": t05, "T06": t06, "T08": t08, "T10": t10, "T11": t11, "T13": t13, "T14": t14,
         "R1": r1, "R2": r2, "R3": r3, "R6": r6}


def ast_label(task: str, code: str | None) -> str:
    if not code:
        return "invalid"
    try:
        f = F(code)
    except (SyntaxError, ValueError):
        return "invalid"
    if "solve" not in f.funcs:
        return "invalid"
    try:
        return RULES[task](f)
    except (RecursionError, KeyError, TypeError):
        return "unknown"

bench_files.runtime_rules.py:
"""Frozen runtime rules for R3_topological_order (snapshot of bench/common/rtrules.py; shared helpers included)."""

"""Runtime-signature rules: tracer feature lines per probe -> mode | 'other' | 'unknown'.

Each rule reads the probe features produced by tracer.py on the probes of probes.py (sizes noted inline).
"""

from __future__ import annotations

import math


def _f(tr, probe):
    p = tr["probes"].get(probe)
    if not p or p.get("error"):
        return None
    return p["features"]


def _get(f, key, sub=None, default=0):
    v = f.get(key, default)
    if sub is not None:
        return (v or {}).get(sub, 0)
    return v


def _maxcalls(f, exclude=("solve", "<genexpr>", "<lambda>", "<listcomp>")):
    c = {k: v for k, v in f["calls"].items() if k not in exclude}
    return max(c.values()) if c else 0


def _frontier(f):
    fifo = _get(f, "deque", "popleft") + f["pop_fifo"] + _get(f, "queue", "fifo_get")
    lifo = _get(f, "deque", "pop") + f["pop_lifo"] + _get(f, "queue", "lifo_get")
    return fifo, lifo


def _lens(f):
    return {int(k): v for k, v in f.get("list_lens", {}).items()}


def t03(tr):
    f = _f(tr, "rand300")
    if f is None:
        return "unknown"
    n, k = 300, 100
    h = f["heap"]
    if f["nsel_args"] or (h.get("heappush", 0) >= k and f["heap_max_size"] <= k + 2) or h.get("heappushpop") \
            or h.get("heapreplace"):
        return "size_k_heap"
    if (f["heapify_sizes"] and max(f["heapify_sizes"]) >= n * 0.9) or (f["heap_max_size"] >= n * 0.9 and h.get("heappop", 0) >= 1):
        return "heapify_pop"
    small_sorts = sum(1 for x in f["sorted_lens"] + f["sort_lens"] if x <= 5)
    if small_sorts >= 20 and f["maxrec"] >= 2:
        return "median_of_medians"
    lens = _lens(f)
    if any(L >= 1500 for L in lens):
        return "counting_sort"
    w = _f(tr, "wide100")
    if w is not None and any(L >= 15000 for L in _lens(w)):
        return "counting_sort"
    big = [x for x in f["sorted_lens"] + f["sort_lens"] if x >= n * 0.98]
    if big:
        return "full_sort"
    mid = [x for x in f["sorted_lens"] + f["sort_lens"] if 0.5 * n <= x < n * 0.98]
    if mid and _get(f, "cint", "hash") >= n * 0.5:
        return "other"  # count + sort of the distinct values
    if small_sorts >= 20:
        return "median_of_medians"
    if _get(f, "cint", "hash") >= n * 0.5:
        return "counting_sort"  # dict counts walked over the value range (no sort of the values)
    if _get(f, "cint", "cmp") >= n and not big:
        return "quickselect"
    return "unknown"


def t04(tr):
    f = _f(tr, "find300")
    if f is None:
        return "unknown"
    n, m = 300, 10
    cs = f["cstr"]
    reads = cs.get("get", 0) + cs.get("iter", 0) + cs.get("slice", 0)
    if (cs.get("find", 0) + cs.get("index", 0) + cs.get("contains", 0) + cs.get("count", 0) + cs.get("split", 0)) >= 1 \
            and reads < 30:
        return "builtin"
    lens = _lens(f)
    if cs.get("concat", 0) >= 1 and any(L in lens for L in (n + m + 1, n + m, n + m + 2)):
        return "z_algorithm"
    cc = f["c_calls"]
    if cc.get("ord", 0) >= n * 0.5 or cc.get("hash", 0) >= n * 0.5 or (cc.get("pow", 0) >= 1 and cc.get("ord", 0) >= m):
        return "rabin_karp"
    if any(L in lens for L in (256, 128, 26, 27)) or (f.get("dict_sizes") and cc.get("get", 0) >= 5):
        return "bmh"
    if m in lens or (m + 1) in lens:
        return "kmp"
    if cs.get("slice", 0) >= n * 0.5 or cs.get("startswith", 0) >= n * 0.5 or cs.get("get", 0) >= n:
        return "naive"
    if cs.get("find", 0) + cs.get("index", 0) + cs.get("contains", 0) >= 1:
        return "builtin"
    return "unknown"


def t05(tr):
    f = _f(tr, "end200")
    if f is None:
        return "unknown"
    n = 200
    ci = f["cint"]
    if ci.get("add", 0) >= n * n / 4:
        return "brute_force"
    sorted_big = any(x >= n * 0.9 for x in f["sorted_lens"] + f["sort_lens"])
    if sorted_big:
        if sum(f["bisect"].values()) >= 1 or ci.get("sub", 0) >= n * 0.3:
            return "sort_binary_search"
        return "sort_two_pointers"
    if ci.get("hash", 0) >= n * 0.3:
        return "hash_map"
    if ci.get("add", 0) >= n * 2:
        return "brute_force"
    return "unknown"


def t06(tr):
    f = _f(tr, "perm200")
    if f is None:
        return "unknown"
    n = 200
    if f["clist_set"] >= 5:
        return "index_marking"
    if f["clist_iter"] >= 4 or f["c_calls"].get("sum", 0) >= 4:
        if f["clist_iter"] >= 4:
            return "value_binary_search"
    if any(x >= n * 0.9 for x in f["sorted_lens"] + f["sort_lens"]):
        return "sort_adjacent"
    idx = f["clist_idx"]
    seq = sum(1 for a, b in zip(idx, idx[1:]) if abs(a - b) <= 1) / max(len(idx) - 1, 1)
    if f["clist_iter"] == 0 and f["clist_get"] >= 20 and _get(f, "cint", "hash") < 5 and f["clist_slice"] == 0 and seq < 0.5:
        return "floyd"
    if f["clist_iter"] == 0 and f["clist_get"] >= 20 and seq >= 0.5:
        return "sort_adjacent"  # neighbour comparison (attempted without the sort)
    if _get(f, "cint", "hash") >= 10:
        return "hash_set"
    lens = _lens(f)
    if any(L in lens for L in (n + 1, n + 2)) and f["clist_iter"] >= 1:
        return "hash_set"
    if f["c_calls"].get("sum", 0) >= 1 or f["c_calls"].get("len", 0) >= 1 and f["clist_iter"] <= 2:
        return "other"
    return "unknown"


def t08(tr):
    fs = [_f(tr, p) for p in ("n64", "n128", "n256")]
    if any(x is None for x in fs):
        return "other" if any(p.get("error") == "timeout" for p in tr["probes"].values()) or tr.get("error") else "unknown"
    l1, l2 = max(fs[1]["lines"], 1), max(fs[2]["lines"], 1)
    expo = math.log2(l2 / l1)
    f = fs[2]
    if expo > 1.6:
        return "other"
    if expo >= 0.6:
        if f["lru"] or f["maxrec"] >= 100 or sum(f["selfrec"].values()) >= 100:
            return "memo_recursion"
        return "iteration"
    lens = _lens(f)
    if lens.get(2, 0) >= 5 or lens.get(4, 0) >= 3:
        return "matrix_power"
    return "fast_doubling"


def t10(tr):
    f = _f(tr, "rand80")
    if f is None:
        return "unknown"
    n, E = 80, 120
    fifo, lifo = _frontier(f)
    fp = _f(tr, "path40")
    deep = fp is not None and fp["maxrec"] >= 20
    if _maxcalls(f) >= 1.5 * E and fifo < n / 2 and lifo < n / 2 and not deep:
        return "union_find"
    if fifo >= n / 2:
        return "bfs"
    if lifo >= n / 2 or sum(f["selfrec"].values()) >= n / 2:
        return "dfs"
    if (f["clist_iter"] >= 2 or f["c_calls"].get("min", 0) >= E) and fifo == 0 and lifo == 0:
        return "label_propagation"
    return "unknown"


def t11(tr):
    f = _f(tr, "rand150")
    if f is None:
        return "unknown"
    n = 150
    if sum(f["bisect"].values()) >= n * 0.5:
        return "patience_bisect"
    if _get(f, "cint", "cmp") >= n * n / 5:
        return "quadratic_dp"
    lens = _lens(f)
    if any(x >= 0.8 * n for x in f["sorted_lens"]) and any(L >= 0.8 * n for L in lens):
        return "fenwick"
    if _get(f, "cint", "cmp") >= n * 2:
        return "patience_bisect"
    return "unknown"


def t13(tr):
    f = _f(tr, "rand80")
    if f is None:
        return "unknown"
    n = 80
    if f["user_classes"] >= 1 and _maxcalls(f) >= n * 0.5:
        return "interval_tree"
    if _maxcalls(f) >= n and _get(f, "cint", "cmp") >= n * n / 4:
        return "union_find"
    if any(x >= n * 0.9 for x in f["sorted_lens"] + f["sort_lens"]):
        return "sort_sweep"
    if _get(f, "cint", "cmp") >= n * n / 4:
        return "union_find"
    return "unknown"


def t14(tr):
    f = _f(tr, "zipf25")
    if f is None:
        return "unknown"
    n, d, k = 325, 25, 4
    if f["most_common"].get("none"):
        return "sort_by_count"
    if f["most_common"].get("n") or f["heap"].get("nlargest") or f["heap"].get("heappush", 0) >= k or f["heap"].get("heapify"):
        return "heap"
    lens = _lens(f)
    if any(L in lens for L in (n + 1, n, n + 2)):
        return "bucket_sort"
    if any(x >= d * 0.9 for x in f["sorted_lens"] + f["sort_lens"]):
        return "sort_by_count"
    if _get(f, "cint", "hash") >= n * 0.5:
        return "quickselect_counts"
    return "unknown"


def r1(tr):
    f = _f(tr, "rand80")
    if f is None:
        return "unknown"
    n = 80
    if f["maxrec"] >= n / 2 or (f["lru"] and sum(f["selfrec"].values()) >= 10):
        return "memo_recursion"
    lens = _lens(f)
    if sum(f["bisect"].values()) >= n * 0.5:
        return "dp_bisect"
    if _get(f, "cint", "cmp") >= n * n / 4 or _get(f, "cint", "eq") >= n * n / 4:
        return "dag_longest_path"
    if (n + 1) in lens and _get(f, "cint", "cmp") >= 3 * n:
        return "dp_bisect"
    if any(x >= n * 0.9 for x in f["sorted_lens"] + f["sort_lens"]):
        return "greedy_end"
    return "unknown"


def r2(tr):
    fc, ff = _f(tr, "cyc_early60"), _f(tr, "forest60")
    if fc is None or ff is None:
        return "unknown"
    n, E = 60, len([1 for v in range(1, 60) if v % 15])
    fifo_f, lifo_f = _frontier(ff)
    fifo_c, lifo_c = _frontier(fc)
    rec_c = sum(fc["selfrec"].values())
    uf_like = _maxcalls(ff) >= 1.5 * E and fifo_f < n / 2 and lifo_f < n / 2 and sum(ff["selfrec"].values()) < n / 2
    if uf_like:
        return "edge_count" if _maxcalls(fc) >= 1.5 * (n - 1) else "union_find"
    visited_c = max(fifo_c, lifo_c, rec_c, fc["calls"].get("dfs", 0))
    if visited_c >= 0.8 * n and (fc["clist_iter"] >= 2 or fc["c_calls"].get("len", 0) >= 1):
        return "edge_count"
    if fifo_f >= n / 2:
        return "bfs_parent"
    if lifo_f >= n / 2 or sum(ff["selfrec"].values()) >= n / 2:
        return "dfs_parent"
    if ff["clist_iter"] >= 1 and fc["c_calls"].get("len", 0) >= 1:
        return "edge_count"
    return "unknown"


def r3(tr):
    fd, fc = _f(tr, "dag40"), _f(tr, "cyc30")
    if fd is None or fc is None:
        return "unknown"
    n = 40
    fifo_d, lifo_d = _frontier(fd)
    if fc["clist_iter"] >= 10:
        return "layering"
    rec_c = sum(fc["selfrec"].values())
    fifo_c, lifo_c = _frontier(fc)
    if rec_c >= 20 or (lifo_c >= 20 and fifo_d < n / 2):
        return "dfs_postorder"
    if sum(fd["selfrec"].values()) >= 5:
        return "dfs_postorder"
    if fifo_d >= n * 0.75 or lifo_d >= n * 0.75 or fd["heap"].get("heappop", 0) >= n * 0.75:
        return "kahn"
    cc = fd["c_calls"]
    if cc.get("next", 0) >= n / 2 or cc.get("remove", 0) + cc.get("discard", 0) >= n / 2 or \
            fd["calls"].get("<genexpr>", 0) >= n:
        return "source_removal"
    if fd["sorted_key"] and any(x >= n * 0.9 for x in fd["sorted_lens"]):
        return "layering"
    return "unknown"


def r6(tr):
    f = _f(tr, "run2000")
    if f is None:
        return "unknown"
    n = 2000
    if sum(f["bisect"].values()) >= 1:
        return "bisect_module"
    reads = f["clist_get"] + f["clist_iter"] * n
    if reads >= n * 0.5:
        return "linear_scan"
    idx = f["clist_idx"]
    dbl = 0
    best = 0
    for a, b in zip(idx, idx[1:]):
        if a > 0 and b in (2 * a, 2 * a + 1, 2 * a - 1):
            dbl += 1
            best = max(best, dbl)
        else:
            dbl = 0
    if best >= 3:
        return "exponential_search"
    run = 0
    best_run = 0
    for a, b in zip(idx, idx[1:]):
        if abs(b - a) == 1:
            run += 1
            best_run = max(best_run, run)
        else:
            run = 0
    if best_run >= 10:
        return "binary_expand"
    if f["clist_get"] >= 5:
        return "binary_search"
    return "unknown"


