def solve(n, prerequisites):
    graph = defaultdict(list)
    in_degree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != n:
        return []

    # Compute longest path depth from sources
    depth = [0] * n
    visited = [False] * n

    def dfs(u):
        visited[u] = True
        max_depth = 0
        for v in graph[u]:
            if not visited[v]:
                max_depth = max(max_depth, dfs(v))
        depth[u] = max_depth + 1
        return depth[u]

    for i in range(n):
        if in_degree[i] == 0:
            dfs(i)

    # Sort nodes by their depth
    result.sort(key=lambda x: depth[x])
    return result

