def solve(n, prerequisites):
    # Initialize in-degree array and adjacency list
    in_degree = [0] * n
    graph = [[] for _ in range(n)]

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    result = []

    # Repeatedly find nodes with in_degree 0 and remove them
    while True:
        found = False
        for i in range(n):
            if in_degree[i] == 0:
                # Remove the node from the graph
