def solve(n, prerequisites):
    # Initialize in-degree array and adjacency list
    in_degree = [0] * n
    graph = [[] for _ in range(n)]

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    result = []
    # Keep track of visited nodes
    visited = [False] * n

    # Repeatedly find nodes with in_degree 0 and remove them
    while True:
        found = False
        for i in range(n):
            if not visited[i] and in_degree[i] == 0:
                # Remove the node
                visited[i] = True
                result.append(i)
                # Decrease in_degree of its neighbors
                for neighbor in graph[i]:
                    in_degree[neighbor] -= 1
                found = True
        if not found:
            break

    # Check if all nodes were visited
    if all(visited):
        return result
    else:
        return []

